<?php
namespace App\Jobs;
use App\Models\{GuestDevice,NotificationDelivery};use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Http;
class SendGuestPushNotification implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=3;public function __construct(public int $deliveryId){}public function handle():void{$d=NotificationDelivery::findOrFail($this->deliveryId);$token=GuestDevice::where('guest_id',$d->guest_id)->whereNotNull('push_token')->latest('last_seen_at')->value('push_token');if(!$token){$d->update(['status'=>'failed','error_message'=>'No registered push token.','failed_at'=>now()]);return;}$project=config('hms_production.firebase.project_id');$access=config('hms_production.firebase.access_token');if(!$project||!$access){$d->update(['status'=>'failed','error_message'=>'Firebase HTTP v1 credentials are not configured.','failed_at'=>now()]);return;}$res=Http::withToken($access)->post("https://fcm.googleapis.com/v1/projects/{$project}/messages:send",['message'=>['token'=>$token,'notification'=>['title'=>$d->subject?:'Hotel update','body'=>$d->body],'data'=>['delivery_id'=>(string)$d->id]]]);if(!$res->successful()){throw new \RuntimeException('FCM delivery failed: '.$res->body());}$d->update(['status'=>'sent','provider'=>'firebase','provider_reference'=>data_get($res->json(),'name'),'sent_at'=>now()]);}}
